  // slice-antislice group
  // This is quite a large group: it has over 15,000,000 elements
  // Shortlex ordering requires too much memory
  // The axiom set here consists of the axioms from halfturn,antislice,and
  // slice with the latter translated into the generators for this group.
  // + a selection of axioms to related the antislice and half turn generators
  // This axiom set is almost certainly not minimal or independent
